for a in delete restore; do
if [ $a = delete ]; then CLS=DeleteClaim; AUD=AuditClaimStatus; H="# Delete a DRAFT claim: any other status is a 409 and writes nothing."; else CLS=RestoreClaim; AUD=AuditClaimRestored; H="# Restore a DELETED claim to a DRAFT, on the sheet's today it was deleted: otherwise a 409 that writes nothing."; fi
